import os

from contextlib import contextmanager
from functools import partial

import torch

from vllm.config import VllmConfig
from vllm.utils.torch_utils import supports_xpu_graph
from vllm.v1.worker.gpu.model_runner import (
    GPUModelRunner as GPUModelRunnerV2,
)
from vllm.v1.worker.gpu_model_runner import GPUModelRunner


class XPUModelRunner(GPUModelRunner):
    """A model runner for XPU devices."""

    def __init__(
        self,
        vllm_config: VllmConfig,
        device: torch.device,
    ):
        with _torch_cuda_wrapper():
            super().__init__(vllm_config, device)
        # FIXME: To be verified.
        self.cascade_attn_enabled = False


class XPUModelRunnerV2(GPUModelRunnerV2):
    """A model runner for XPU devices."""

    def __init__(
        self,
        vllm_config: VllmConfig,
        device: torch.device,
    ):
        with _torch_cuda_wrapper():
            super().__init__(vllm_config, device)


    @torch.inference_mode()
    def capture_model(self, *, profile_only: bool = False) -> int:
        result = super().capture_model(profile_only=profile_only)
        if (
            not profile_only
            and os.environ.get("B70_XPU_POST_CAPTURE_WARMUP") == "1"
            and self.parallel_config.tensor_parallel_size > 1
        ):
            from vllm.distributed import get_tp_group
            from vllm.logger import init_logger

            # In the installed XCCL stack a large first eager all-reduce after
            # graph capture can propagate recording state onto the caller's
            # queue. A small post-capture collective avoids that transition.
            # Initializing it before capture is insufficient (four-rank repro).
            # This is startup-only and does not alter any model/request state.
            stream = torch.xpu.current_stream(self.device)
            if torch.xpu.is_current_stream_capturing():
                raise RuntimeError("Post-capture warmup entered during capture")
            warmup = torch.zeros(2560, dtype=torch.bfloat16, device=self.device)
            torch.distributed.all_reduce(warmup, group=get_tp_group().device_group)
            if torch.xpu.is_current_stream_capturing():
                raise RuntimeError("XCCL warmup left the inference queue recording")
            stream.synchronize()
            init_logger(__name__).info(
                "B70 XPU: post-capture eager collective warmup complete"
            )
        return result


@contextmanager
def _torch_cuda_wrapper():
    # Replace cuda APIs with xpu APIs. Each callable gets its own functools.partial
    # so it is not the same object as torch.xpu.* (Torch Dynamo _get_handlers()
    # asserts on duplicate registration when cuda aliases xpu directly).
    torch.cuda.Stream = torch.xpu.Stream
    torch.cuda.default_stream = partial(torch.xpu.current_stream)
    torch.cuda.current_stream = partial(torch.xpu.current_stream)
    torch.cuda.stream = partial(torch.xpu.stream)
    torch.cuda.set_stream = partial(torch.xpu.set_stream)

    # torch.xpu.Event does not accept the ``blocking`` kwarg that
    # torch.cuda.Event supports, so drop it here.
    def _xpu_event(*args, blocking=None, **kwargs):
        return torch.xpu.Event(*args, **kwargs)

    torch.cuda.Event = _xpu_event
    if supports_xpu_graph():
        torch.cuda.graph = partial(torch.xpu.graph)
        torch.cuda.CUDAGraph = torch.xpu.XPUGraph
        torch.cuda.graph_pool_handle = partial(torch.xpu.graph_pool_handle)
        torch.cuda.is_current_stream_capturing = torch.xpu.is_current_stream_capturing
    yield
